import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`niche-validator`,heroTitle:`Validate your niche in minutes`,heroSubtitle:`Perplexity Computer measures demand velocity, supplier signals, and market saturation so you know whether a dropshipping niche is worth pursuing before you build.`,inputUrlCta:`Validate this niche`,inputUrlPlaceholder:`e.g. minimalist jewelry`,inputUrlPrefill:`Evaluate the niche '{url}' for dropshipping potential. (1) Research demand signals using trend velocity, search interest, social momentum, and marketplace activity. (2) Analyze supplier availability, fulfillment quality, shipping complexity, and margin potential. (3) Benchmark the niche against existing stores to measure competition, offer saturation, and content quality. (4) Score the niche on demand, competition, margins, and operational complexity. (5) Recommend 10 product ideas within the niche with reasons each one is promising. (6) Deliver a go or no-go verdict with the data behind it and the fastest path to launch if the niche is viable.`,heroOverlaySteps:[`Measuring trend velocity, search demand, and social momentum for the niche`,`Reviewing supplier quality, shipping realities, and product margin potential`,`Comparing market saturation and the strength of competing stores`,`Niche scorecard, product picks, and a go or no-go verdict ready to review`],generatingSteps:[`Researching '{url}' to understand the niche, buyer demand, and product landscape`,`Designing an agent to compare demand, supplier quality, and saturation across the niche`,`Configuring scoring for viability, margins, operational risk, and launch upside`,`Packaging the findings into a niche report with product ideas and a launch recommendation`],featureSectionTitle:`From niche idea to launch verdict`,featureCardTitles:[`Connects to your store research stack`,`Outputs you can act on today`],featureCardDescriptions:[`Computer breaks the work into demand research, supplier evaluation, competitor analysis, and scoring so the recommendation is grounded in signals instead of guesswork.`,`AliExpress, trend tools, Google Sheets, Notion, and launch planning docs can stay connected so niche research turns into execution without rebuilding the work manually.`,`Demand score. Saturation readout. Supplier risk notes. Ten product ideas. Clear go or no-go call. Computer delivers the report you need before spending on a store.`],capabilitySectionTitle:`Your niche analyst, on demand`,capabilitySectionSubtitle:`Enter a niche idea, step away, and come back to a viability report with product picks.`,capabilityCards:[{title:`Demand Signals`,description:`Computer can measure trend velocity, search interest, and marketplace activity so you see whether the niche has real demand behind it.`},{title:`Supplier Screening`,description:`Computer can compare supplier quality, shipping constraints, order volume, and margin headroom before you commit to the niche.`},{title:`Saturation Analysis`,description:`Computer can benchmark the niche against competing stores and identify where the market is too crowded or still open.`},{title:`Connect Your Tools`,description:`Computer can organize the findings across Sheets, Notion, and planning docs so niche research flows directly into launch preparation.`},{title:`Product Shortlisting`,description:`Computer can identify promising products inside the niche and explain which demand and margin signals make them stand out.`},{title:`Decision Refresh`,description:`Computer can revisit the niche later, compare new demand signals, and tell you whether the launch window is improving or closing.`}]});export{t as default};
